using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using UnityEngine;
namespace Yixuan.AI.Tasks {
 public partial class TaskMissionRunner {
  public TaskContract Contract{get;private set;}public TaskRuntimeContext Context{get;private set;}
  TaskContract _testContract;string _contractExtractionPrompt;
  public bool SubmitContractTest(string request,string source,TaskContract contract){_testContract=contract;try{return SubmitCodeForTest(request,source);}finally{_testContract=null;}}
  void EmitRuntime(string type,string tool="",string status="",string detail=""){
   if(Context==null)return;var e=Context.Emit(type,tool,status,detail);File.AppendAllText(Path.Combine(RunDirectory,"events.jsonl"),JsonUtility.ToJson(e)+"\n",Encoding.UTF8);
  }
  IEnumerator BindContract(int generation,TaskContract fixture){
   Phase="intent_contract";Raise();Contract=null;
   if(fixture!=null){Contract=fixture;Evidence.contract_source="test_fixture";}
   else {
    Evidence.contract_source="independent_core_llm";string raw=null,error=null;
    var targets=new List<DestinationSnapshot>();foreach(var t in Catalog.SemanticTargets())targets.Add(t.Snapshot());
    var actions=new StringBuilder();foreach(var a in TaskGestureSkills.Available())actions.AppendLine(a.Id+" = "+a.Label);
    string prompt=@"Extract a task INTENT CONTRACT independently from the user's request. Return JSON only, not Lua and not an execution script. Do not infer requirements from generated code. Preserve EVERY requested step, count, negation, condition and ordering. The contract records obligations/results, while Lua chooses functions, loops and strategies. Never substitute unavailable or ambiguous targets; return error with a clarification.
Schema: {version:'task-contract/1',error:'',forbid_move:false,forbid_body_turn:false,forbid_speech:false,forbid_interact:false,conditions:[{id:'q1',source:'exact substring',question:'one exact yes/no proposition in Chinese',max_age:120}],obligations:[{id:'m1',source:'exact substring of request',kind:'return',target_id:'origin',action_id:'',direction:'',text:'',emotion:'',min_duration:0,distance:0,angles_exact:false,pitch:0,yaw:0,reference:'body',count:1,after:[],overlap:[],condition_id:'',branch:'',repeat_group:'',final:false,max_age:0,camera_only:false,during_target:'',at_progress:0,every_meters:0}]}.
Use kind navigate/look_at/look_direction/turn_body/gesture/interact/observe/check/return/speak/express/wait. Each source MUST literally occur in the user input. Origin/起点/原点/起始位置 means SCENE origin, unless explicitly this mission's start -> mission_origin. Returning by WALKING must use kind return; looking at an origin uses look_at. Targets and actions must use exact catalog IDs. Counts 1..32. after lists earlier obligation IDs; overlap lists obligations that MUST overlap. Only constrain order actually requested. For an alternating/repeated SEQUENCE such as go to X then return, repeat five times, assign ALL sequence members the SAME repeat_group (e.g. roundtrip), each count=5, in their requested sequence order. An after dependency WITHIN that repeat_group means same iteration, and the next iteration starts after the preceding iteration finishes. A count WITHOUT repeat_group repeats a single obligation and after acts as an ALL-occurrences barrier. Never encode alternating cycles as count=N navigate then count=N return with no repeat_group. Never split the first iteration and remaining iterations unless explicitly requested. Independent repeated gestures can use count without a group. Every repeat_group must be contiguous with equal counts. After the entire loop may reference the last member ID. final=true ONLY for an explicit final persistent pose/location, not earlier milestones. max_age=0 for historical milestones. Each requested waypoint/gesture needs its own obligation. Do not let final position stand in for earlier visits.
Sky/up/down gaze MUST use look_direction direction up/down/forward/left/right, never camera_front or nearby objects. 抬头看天空 alone requires geometric direction only; if user asks what it looks like or a visual condition, add check with its exact question after gaze. Observe means actual 4-direction semantic scan, not just looking at a single target. For a condition, add an unconditional check obligation (text=exact conditions.question), then gated obligations with condition_id and branch true/false/unknown. Unknown is NOT false. Do not add an unrequested else branch. Keep base check obligation unconditional. Gated steps may depend on unconditional prefix; don't require inactive branch completion. Negated requests are permissions only, NEVER positive obligations: 不要说话 => forbid_speech=true and NO speak obligation. For express use emotion=happy or neutral, NEVER action_id; action_id is ONLY for gesture. Preserve explicit seconds in min_duration for wait/express. Preserve explicitly requested numeric camera angles with angles_exact=true and pitch/yaw/reference; qualitative gaze has angles_exact=false. No invented speech/gestures/interaction. Do not add final report obligation. Global flags apply to the whole task. A local restriction AFTER navigation (先走到X，然后站在原地看Y) must NOT become global forbid_move. Local stationary look_at is implemented without translation; local camera-only uses that obligation.camera_only=true. If an arbitrary requested local permission cannot be expressed faithfully, return error. Standing still forbids translation, not rotation. Only camera forbids translation AND body rotation; camera_only=true for look_at. Explicit silence forbids ALL audible speech including acknowledgment. Speech text is exact only for explicit quoted words, otherwise empty. Condition source is an exact user phrase. If you cannot faithfully represent a requirement, return error rather than silently omit it.
";
    prompt+="\nFor an explicit BODY rotation use kind=turn_body, yaw=signed degrees, reference=body, angles_exact=true; right is positive, left negative; finite nonzero -180..180 degrees. Body rotation does NOT require a destination or translation. Do not substitute camera gaze for body rotation. 面向我/脸朝向我/把脸转向我 means look_at viewer without movement unless explicit translation/distance is requested. Never invent move_relative from a false start such as 冲向我 when the corrected phrase asks only to face the viewer.\nRelative movement MUST use kind=move_relative, direction=forward/backward/left/right, distance in meters. One requested step means 0.4m; 往前走两步 means forward distance=0.8. Directions refer to body yaw at the START of that step, not a fixed anchor or the viewer. Do NOT use navigate anchor/camera_front for relative movement. Preserve exact requested count/distance. distance is finite 0.05..4m; reject larger or ambiguous unbounded movement rather than invent a destination. move_relative preserves body yaw and travels in a straight line with collision checks.\nTool registry:\n"+TaskToolRegistry.Prompt()+"\nTargets:\n"+JsonUtility.ToJson(new TargetList{targets=targets.ToArray()})+"\nActions:\n"+actions+"\nUSER DATA: "+Evidence.request;
    if(IsInsertion)prompt+="\nRUNTIME CONTEXT: The original mission is SUSPENDED with its Lua VM and unfinished loop retained. This request inserts a temporary stationary action. Extract ONLY inserted gesture/expression/speech/wait obligations. Stop/pause and resume/continue unfinished mission are handled by the runtime, not child tool obligations. Do NOT add return/navigate or recreate the original mission. Preserve the inserted action faithfully. Parent request DATA: "+_parentMission.Evidence.request;
    prompt+="\nROUTE PROGRESS SEMANTICS: Lua can now advance a planned A* route incrementally with game.follow_route. For \"走到X，在路中间停一次挥手，然后继续走\", output ONE gesture obligation with during_target=X,at_progress=0.5, and ONE final navigate X obligation after the gesture. Do NOT encode a full arrival before the intermediate action and do NOT invent move_relative. \"在这中间/途中/半路停一次\" may use 0.5 as the chosen intermediate checkpoint; \"走到一半\" specifically requires 0.5 of original planned PATH LENGTH. An action with during_target MUST have EXACTLY ONE of at_progress (0<f<1) or every_meters (0.05..4). For \"每走一步挥手\", use gesture during_target=X,every_meters=0.4,count=1; runtime checks an action after EVERY route segment including the last short segment. It is dynamic repetition, not one wave and not a guessed count. For this periodic case final arrival obligation has NO after dependency on the periodic effect, since its last occurrence may follow the final short segment. All schedules require a final navigate X or return origin/mission_origin obligation. source must still be a literal user substring. Do not add wait for an implicit stop: segment execution stops before yielding. For an explicitly requested wait duration add a scheduled wait obligation. Other intermediate stationary effects (speak/express/look_at/check) use the same schedule fields. Return-home path can be segmented using target origin/mission_origin.\nGAZE AT HOME: 看向原点/看一下原点 means kind=look_at,target_id=origin, WITHOUT translation. The ID origin can be looked at as a coordinate reference. Never substitute a return obligation for gaze. Only explicit walking/returning uses return.\n";
    _contractExtractionPrompt=prompt;Write("contract_prompt.txt",prompt);yield return CallCore(prompt,(v,e)=>{raw=v;error=e;});if(generation!=_generation)yield break;
    Write("contract_raw.txt",raw??error??"empty");try{Contract=JsonUtility.FromJson<TaskContract>(ExtractJson(raw));}catch(Exception ex){error=ex.Message;}
    if(Contract==null){Finish("rejected","intent_contract_unavailable: "+error);yield break;}
   }
   ApplyExplicitPermissions();
   NormalizeContract();
   string invalid=TaskContractRules.Validate(Contract,Evidence.request,id=>Catalog.Get(id)!=null,id=>TaskGestureSkills.Get(id)!=null);
   if(invalid!=null&&fixture==null&&string.IsNullOrEmpty(Contract.error)){
    string repaired=null,repairError=null;yield return CallCore(_contractExtractionPrompt+"\nThe extraction failed independent validation BEFORE effects: "+invalid+"\nPrevious JSON: "+JsonUtility.ToJson(Contract)+"\nReturn a corrected complete contract, preserving the original request.",(v,e)=>{repaired=v;repairError=e;});if(generation!=_generation)yield break;
    Write("contract_repair_raw.txt",repaired??repairError??"empty");try{Contract=JsonUtility.FromJson<TaskContract>(ExtractJson(repaired));}catch{}
    if(Contract==null){Finish("rejected","contract_repair_failed");yield break;}ApplyExplicitPermissions();NormalizeContract();invalid=TaskContractRules.Validate(Contract,Evidence.request,id=>Catalog.Get(id)!=null,id=>TaskGestureSkills.Get(id)!=null);
   }
   Write("contract.json",JsonUtility.ToJson(Contract,true));Evidence.contract=Contract;
   if(invalid!=null){Finish("rejected","intent_contract_invalid: "+invalid);yield break;}
   string insertionInvalid=ValidateInsertionContract();Write("contract.json",JsonUtility.ToJson(Contract,true));if(insertionInvalid!=null){Finish("rejected",insertionInvalid);yield break;}
   if(!VoiceEnabled)foreach(var o in Contract.obligations)if(o.kind=="speak"&&string.IsNullOrEmpty(o.condition_id)){Finish("rejected","task_speech_disabled: 请先在任务面板开启任务语音；已在移动前中止，避免走到一半才发现无法说话");yield break;}
   if(Context!=null)Context.Muted=Contract.forbid_speech;
   if(Session!=null&&!IsInsertion)Session.TaskAcknowledgment(Evidence.request);
   if(Context!=null){EmitRuntime("ContractAccepted","","",JsonUtility.ToJson(Contract));}
  }
  void ApplyExplicitPermissions(){TaskContractRules.ApplyExplicitPermissions(Contract,Evidence.request);}
  void NormalizeContract(){
   if(Contract==null)return;
   bool explicitCameraOnly=Regex.IsMatch(Evidence.request,@"只(转|动)(镜头|相机)|禁止身体转向|不要身体转向|不许身体转向");
   foreach(var o in Contract.obligations??new TaskObligation[0])if(o.kind=="look_at"&&!Contract.forbid_body_turn&&!explicitCameraOnly)o.camera_only=false;
  }
  public void RuntimeNotice(string type,string detail){RuntimeNotice(Context,type,detail);}
  public void RuntimeNotice(TaskRuntimeContext ctx,string type,string detail){if(ctx==null)return;var e=ctx.Emit(type,"","",detail);if(!string.IsNullOrEmpty(ctx.EvidenceDirectory))File.AppendAllText(Path.Combine(ctx.EvidenceDirectory,"events.jsonl"),JsonUtility.ToJson(e)+"\n",Encoding.UTF8);}
  string CheckCompletion(bool program){var check=TaskContractRules.Evaluate(Contract,Evidence.results,program,TaskNow,_generation);Evidence.completion=check;Write("completion.json",JsonUtility.ToJson(check,true));EmitRuntime("CompletionChecked","",check.task_succeeded?"succeeded":"failed",check.reason);return check.task_succeeded?null:check.reason;}
 }
}
